{
  "facts": [
    {
      "topic": "target_route",
      "statement": "The harness reads two unsigned values from the first eight input bytes as parser and renderer flags, then passes all remaining bytes to md_html as Markdown. Inputs shorter than those two values return before the call.",
      "evidence": [
        {
          "unit_id": "u-1056c6fa42072a012709",
