      "absence_claim": false,
      "audited_unit_ids": []
    },
    {
      "topic": "configuration",
      "statement": "The supplied recipe configures CMake with BUILD_SHARED_LIBS=OFF and links fuzz-mdhtml against libmd4c-html.a and libmd4c.a.",
      "evidence": [
        {
          "unit_id": "u-9425ff77c711ce4cae9b",
          "start_line": 21,
          "end_line": 26,
          "role": "primary",
          "dependency_reason": ""
        }
      ],
