    },
    {
      "topic": "contract",
      "statement": "The after parser resolves a later double pipe against a stored opener when spoiler parsing is enabled, then emits MD_SPAN_SPOILER enter and leave callbacks for resolved double-pipe marks.",
      "evidence": [
        {
          "unit_id": "u-3e73bbc2708be8760b6c",
