          "end_line": 496,
          "role": "primary",
          "dependency_reason": ""
        }
      ],
      "absence_claim": false,
      "audited_unit_ids": []
    },
    {
      "topic": "counterevidence",
      "statement": "A finite target route exists for the frozen spoiler-span tuple: supply MD_FLAG_SPOILERS in the first unsigned word, zero renderer flags in the second, and ordinary paragraph text such as ||x|| afterward. The harness forwards those values to md_html, which forwards the parser flag to the parser and installs the callbacks that handle the emitted spoiler span.",
